export function formatPrice(cents: number, currency = 'USD'): string {
  const value = (cents / 100).toFixed(2);
  return `${currency} ${value}`;
}

export function parsePrice(input: string): number {
  const n = Number(input.replace(/[^0-9.]/g, ''));
  return Math.round(n * 100);
}

export interface LineItem {
  sku: string;
  price: number;
  qty: number;
}

export function subtotal(items: LineItem[]): number {
  return items.reduce((sum, i) => sum + i.price * i.qty, 0);
}

export function total(items: LineItem[], taxRate: number): number {
  const sub = subtotal(items);
  return sub + sub * taxRate;
}

export function isEmpty(items: LineItem[]): boolean {
  return items.length === 0;
}

export function search(items: string[], q: string): string[] {
  const needle = q.toLowerCase();
  return items.filter((i) => i.toLowerCase().includes(needle));
}

export interface Order {
  id: string;
  placedAt: string;
  totalCents: number;
}

export async function listOrders(): Promise<Order[]> {
  const res = await fetch('/api/orders');
  return res.json();
}

