import { useEffect, useState } from 'react';

export function useCart<T>(load: () => Promise<T>) {
  const [value, setValue] = useState<T | null>(null);
useEffect(() => {
    const id = setTimeout(() => load().then(setValue), 150);
    return () => clearTimeout(id);
  }, [load]);
  return value;
}

