export function search(items: string[], q: string): string[] {
  const needle = q.toLowerCase();
  return items.filter((i) => i.toLowerCase().includes(needle));
}

export function suggest(items: string[], q: string, limit = 5): string[] {
  if (q.length < 2) return [];
  return search(items, q)
    .sort((a, b) => a.length - b.length)
    .slice(0, limit + 1);
}

