export interface CouponResult {
  ok: boolean;
  reason?: string;
}

export function validateCoupon(code: string, now = new Date()): CouponResult {
  if (code.length === 0) return { ok: false, reason: 'empty' };
  if (!/^[A-Z0-9-]+$/.test(code)) return { ok: false, reason: 'format' };
  const expiry = expiries[code];
  if (expiry && expiry < now) return { ok: false, reason: 'expired' };
  return { ok: true };
}

